#!/usr/bin/env bash
# ─────────────────────────────────────────────────────────────
# Structura — apply read-aloud, celebrations and the first-run tour.
#
#   bash apply-structura-features.sh
#
# Everything is inside this one file: the change set, the checkpoint script,
# and the checks that stop it doing damage.
#
# What it does, in order:
#
#   1. Refuses to run anywhere that is not the Structura repo root.
#   2. Commits whatever is currently uncommitted and tags it `pre-features`,
#      so there is a named point to return to before anything is touched.
#   3. Verifies the change set against a checksum, then dry-runs it. If the
#      dry run fails, NOTHING is applied — a half-applied change set is the
#      worst state to debug from.
#   4. Applies it, installs scripts/checkpoint.sh, and runs the test suite.
#
# The changes are left UNCOMMITTED on purpose, so `git diff` is reviewable and
# `git checkout .` undoes the lot instantly.
#
# Flags:
#   --no-tests    skip the suite (it takes a minute)
#   --no-backup   do not commit or tag first (you have your own checkpoint)
#   --revert      take the changes back out again
# ─────────────────────────────────────────────────────────────
set -euo pipefail

PATCH_SHA="2bf0f0cddba9ad823db59c5a1dbf035af58e3c361578ecae594ac905df0c5d21"

RUN_TESTS=1
BACKUP=1
REVERT=0
for arg in "$@"; do
  case "$arg" in
    --no-tests)  RUN_TESTS=0 ;;
    --no-backup) BACKUP=0 ;;
    --revert)    REVERT=1 ;;
    -h|--help)   sed -n '2,26p' "$0" | sed 's|^# \{0,1\}||'; exit 0 ;;
    *) echo "Unknown option: $arg"; echo "Try: bash $0 --help"; exit 1 ;;
  esac
done

say()  { printf '\n\033[1m==> %s\033[0m\n' "$1"; }
warn() { printf '\033[33m    %s\033[0m\n' "$1"; }
die()  { printf '\n\033[31mStopped: %s\033[0m\n\n' "$1" >&2; exit 1; }


# Which base64 flag this system uses. Checked rather than assumed, because a
# silent decode failure would look like a corrupt payload.
if printf 'aGk=' | base64 -d >/dev/null 2>&1; then
  B64D="base64 -d"
elif printf 'aGk=' | base64 -D >/dev/null 2>&1; then
  B64D="base64 -D"
else
  die "no usable base64 decoder on this machine."
fi

# The change set and the checkpoint script, carried inside this file.
# Base64 rather than a raw diff: a patch is whitespace-sensitive to the byte,
# and browsers, editors and mail clients all rewrite trailing whitespace on
# long lines without saying so.
extract_payload() {
  $B64D > "$1" <<'__STRUCTURA_PATCH_B64__'
ZGlmZiAtLWdpdCBhL0FwcC5qcyBiL0FwcC5qcwppbmRleCAyMDIxOTE0Li5iNzUyODVhIDEwMDY0NAotLS0gYS9BcHAuanMKKysr
