# ── 1. Am I in the right place? ──────────────────────────────
say "Checking where I am"

[ -d .git ] || die "this is not a git repository. cd to /workspaces/Structura_App first."

for f in App.js src/engine/index.js scripts/run-tests.mjs; do
  [ -f "$f" ] || die "$f is missing — this does not look like the Structura repo root."
done

REPO="$(basename "$(pwd)")"
if [ "$REPO" != "Structura_App" ]; then
  warn "Directory is '$REPO', expected 'Structura_App'. Continuing, but check you are in the right repo."
fi
echo "    $(pwd) on branch $(git rev-parse --abbrev-ref HEAD)"

# ── 2. Unpack the payloads ───────────────────────────────────
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT
extract_payload "$WORK/features.patch" "$WORK/checkpoint.sh"

GOT="$(sha256sum "$WORK/features.patch" | cut -d' ' -f1)"
[ "$GOT" = "$PATCH_SHA" ] || die "the embedded change set is corrupt (checksum mismatch).
    Re-download this file — some editors and mail clients rewrite long lines."

# ── revert ───────────────────────────────────────────────────
if [ "$REVERT" -eq 1 ]; then
  say "Reverting"
  if git apply --reverse --check "$WORK/features.patch" 2>/dev/null; then
    git apply --reverse "$WORK/features.patch"
    echo "    Removed. Every source file is back to where it was."
    echo "    scripts/checkpoint.sh is left in place — it is a tool, not part"
    echo "    of the features. Delete it if you do not want it."
    exit 0
  fi
  die "the changes are not cleanly present, so they cannot be cleanly removed.
    If you committed them:   git reset --hard pre-features
    To see what differs:     git status"
fi

# ── 3. Backup ────────────────────────────────────────────────
if [ "$BACKUP" -eq 1 ]; then
  say "Making a point to come back to"
  if [ -n "$(git status --porcelain)" ]; then
    git add -A
    git commit -qm "working state before read-aloud / celebration / tour"
    echo "    Committed your uncommitted work first."
  else
    echo "    Tree is already clean."
  fi
  if git rev-parse -q --verify refs/tags/pre-features >/dev/null; then
    TAG="pre-features-$(date +%Y%m%d-%H%M)"
    warn "Tag 'pre-features' already exists — using '$TAG' instead."
  else
    TAG="pre-features"
  fi
  git tag -a "$TAG" -m "before read-aloud, celebrations and the first-run tour"
  echo "    Tagged $TAG at $(git rev-parse --short HEAD)"
else
  TAG="(no backup made)"
fi

# ── 4. Dry run, then apply ───────────────────────────────────
say "Checking the change set applies cleanly"

if git apply --reverse --check "$WORK/features.patch" 2>/dev/null; then
  die "these changes are already applied to this tree. Nothing to do.
    To take them back out:  bash $0 --revert"
fi

if ! git apply --check "$WORK/features.patch" 2>/dev/null; then
  echo
  git apply --check "$WORK/features.patch" || true
  die "the change set does not fit this tree, so nothing has been applied.
    Your tree has drifted from the version this was built against.
    Nothing was changed by this script beyond the backup commit above."
fi
echo "    Clean. 25 files: 10 added, 15 modified, none deleted."

say "Applying"
git apply "$WORK/features.patch"
install -m 0755 "$WORK/checkpoint.sh" scripts/checkpoint.sh
echo "    Done, and scripts/checkpoint.sh installed."

# ── 5. Tests ─────────────────────────────────────────────────
TESTS="skipped"
if [ "$RUN_TESTS" -eq 1 ]; then
  if [ ! -f package.json ]; then
    warn "No package.json — skipping tests. Run scripts/bootstrap.sh first."
  elif [ ! -d node_modules ]; then
    warn "node_modules is missing — run 'npm install', then 'npm test'."
  else
    say "Running the suite"
    if npm test; then
      TESTS="all 50 suites passed"
    else
      TESTS="FAILED"
      warn "Tests failed. The changes are applied but uncommitted."
      warn "To undo everything:  git checkout . && git clean -fd"
    fi
  fi
fi

# ── Done ─────────────────────────────────────────────────────
cat <<DONE

─────────────────────────────────────────────────────────
 Applied. Tests: ${TESTS}

 Nothing is committed yet, on purpose.

   git diff --stat          see what changed
   git checkout . && git clean -fd
                            undo all of it, right now
   bash $0 --revert
                            same thing, more precisely

 When you are happy with it:

   git add -A
   git commit -m "read-aloud, end-of-lesson celebration, first-run tour"
   git push origin \$(git rev-parse --abbrev-ref HEAD) --tags

 Push the tags — ${TAG} only exists in this Codespace until you do,
 and a Codespace can be rebuilt out from under you.

 Then, on a phone:

   npm run tunnel

 Worth checking on the A35: Account -> Reading and sound -> Reading voice.
 No platform reports a voice's gender, so on Android the automatic choice is
 a guess — use the play buttons and pick one by ear.
─────────────────────────────────────────────────────────

DONE
